e", "price_field", "price", "source", "kind", "direction"], "title": "Trigger", "type": "object"}, "TriggerSource": {"additionalProperties": false, "properties": {"timeframe": {"const": "M15", "title": "Timeframe", "type": "string"}, "bar_index": {"minimum": 0, "title": "Bar Index", "type": "integer"}, "open_time_ms": {"minimum": 0, "title": "Open Time Ms", "type": "integer"}, "close_time_ms": {"minimum": 0, "title": "Close Time Ms", "type": "integer"}}, "required": ["timeframe", "bar_index", "open_time_ms", "close_time_ms"], "title": "TriggerSource", "type": "object"}}, "additionalProperties": false, "properties": {"schema": {"const": "brooks.trade-intent.v2", "title": "Schema", "type": "string"}, "role": {"const": "TRADER", "title": "Role", "type": "string"}, "decision": {"enum": ["ENTER_LONG", "ENTER_SHORT", "NO_TRADE"], "title": "Decision", "type": "string"}, "symbol": {"title": "Symbol", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "market_context": {"anyOf": [{"additionalProperties": true, "type": "object"}, {"type": "null"}], "title": "Market Context"}, "setup": {"anyOf": [{"$ref": "#/$defs/Setup"}, {"type": "null"}]}, "decision_timeframe": {"anyOf": [{"const": "M15", "type": "string"}, {"type": "null"}], "title": "Decision Timeframe"}, "context_timeframes_used": {"items": {"type": "string"}, "title": "Context Timeframes Used", "type": "array"}, "entry_mechanism": {"enum": ["continuation", "breakout", "breakout_pullback", "reversal", "none", "unclear"], "title": "Entry Mechanism", "type": "string"}, "trigger": {"anyOf": [{"$ref": "#/$defs/Trigger"}, {"type": "null"}]}, "invalidation": {"anyOf": [{"$ref": "#/$defs/PriceReference"}, {"type": "null"}]}, "evidence_for": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence For", "type": "array"}, "evidence_against": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence Against", "type": "array"}, "qualitative_confidence": {"enum": ["high", "medium", "low"], "title": "Qualitative Confidence", "type": "string"}, "uncertainty": {"items": {"type": "string"}, "minItems": 1, "title": "Uncertainty", "type": "array"}, "conditions_that_change_market_read": {"items": {"type": "string"}, "minItems": 1, "title": "Conditions That Change Market Read", "type": "array"}}, "required": ["schema", "role", "decision", "symbol", "decision_time_ms", "market_context", "setup", "decision_timeframe", "context_timeframes_used", "entry_mechanism", "trigger", "invalidation", "evidence_for", "evidence_against", "qualitative_confidence", "uncertainty", "conditions_that_change_market_read"], "title": "TradeIntentV2", "type": "object"}
Input: {"decision_time_ms": 1790135999999, "macro_contexts": {"D1": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1790121599999, "directional_pressure": "bull", "evidence_against": ["Most of the recent window is range, not trend: bars 51-84 (34 bars) and 88-107 (20 bars) are overlapping two-sided structures, so 54 of the last 69 bars are range bars even though the swing sequence is bullish.", "Price is at the extreme top of the window and bar 119 (high 2776.18, close 2752.43) fails to exceed bar 118's 2850 and closes below its open, a pause bar immediately after a spike bar.", "Upper tails appear on the largest bars: bar 118 closes 74.39 below its 2850 high on a 208-point range (about 36 percent of the bar) and bar 85 closes 41.64 below its 2293.80 high, showing selling into strength at the highs.", "The advance from 1916.51 (bar 85) to 2850 (+49 percent) in 34 bars has had no sustained multi-bar retracement after bar 87, a profile at least as compatible with spike/climax behaviour as with a mature channel; in this method a spike leg alone does not establish that the next leg continues."], "evidence_for": ["Swing progression since bar 31 is a clean sequence of higher highs and higher lows: 1944.39 (bar 50) to 2771 (bar 87) to 2850 (bar 118), with rising lows at 1512.91 (bar 31), 1803.74 (bar 52), 2357.18 (bar 99) and 2358.62 (bar 112).", "Two large bull bars produced accepted breakouts: bar 85 (range 388, close 2252.16) ended the 34-bar 1803.74-1974.46 range and price never closed back below 2111 (bar 86 low); bar 118 then closed 2775.61 near the window high after taking out 2771.", "Pullbacks inside the post-bar-85 advance are shallow relative to the legs (2557.46 to 2357.18 is about 8 percent), and the 20-bar consolidation at bars 88-107 held well above the prior breakout, the behaviour of a trending market rather than a two-sided range.", "Nine of the last twelve bars (108, 109, 111, 113, 114, 115, 116, 117, 118) closed above their opens, and the last five closes are all above 2397, so the most recent leg has directional follow-through."], "missing_information": [], "observations": ["120 closed D1 bars, first open_time 1779753600000 (open 2109.85) to last open_time 1790035200000 (close 2752.43); window high 2850 at bar 118, window low 1368.42 at bar 11.", "Bars 0-11 fall from high 2138.82 (bar 0) to low 1368.42 (bar 11); bar 11 (open 1581.32) closes 1568.55, leaving a ~200-point lower tail, and bar 12 immediately reverses to close 1687.83.", "Bars 12-36 are two-sided and heavily overlapping between low 1512.91 (bar 31) and high 1845.09 (bar 20); bars 22-36 form a narrower lower band with three tests of 1551.60-1560.05.", "Bars 37-50 close progressively higher; bar 49 (open 1775.60) closes 1889.93 and bar 50 prints high 1944.39.", "Bars 51-84 rotate in a 34-bar range between 1803.74 (bar 52 low) and 1974.46 (bar 62 high); bars 74-84 tighten to roughly 1868-1919 on small-range bars.", "Bar 85 (open 1916.51) closes 2252.16 at high 2293.80 with a 388-point range, breaking out of that 34-bar range; bars 86-87 extend the leg to 2771.", "Bars 88-107 hold above the breakout in a 20-bar range between 2357.18 (bar 99 low) and 2557.46 (bar 93 high).", "Bar 108 (open 2437) closes 2514.72 at high 2680; bars 110-114 pull back to 2358.62 (bar 112 closes 2397.10).", "Bars 115-118 close 2612.02, 2632.98, 2642.90 and 2775.61, taking out 2771 to a new window high 2850; bar 119 (open 2775.60, high 2776.18, low 2716.01, close 2752.43) is a small bear bar that fails to exceed bar 118's high."], "phase": "breakout-spike", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Bear swing, bars 0-11: eleven lower closes from 2072.79 to 1568.55; 12 bars carry price from the 2138.82 window high down to 1368.42, and bar 11's long lower tail with a close back at 1568.55 marks climactic rejection of that low rather than a clean close at the extreme.", "end_time_ms": 1780790399999, "kind": "swing", "lower_boundary": "1368.42", "start_time_ms": 1779753600000, "upper_boundary": "2138.82"}, {"description": "Post-selloff trading range, bars 12-36: two-sided, overlapping bars between 1512.91 (bar 31 low) and 1845.09 (bar 20 high); the second half (bars 22-36) sits in a lower band near 1551-1740 with three separate low tests around 1551.60-1560.05.", "end_time_ms": 1782950399999, "kind": "range", "lower_boundary": "1512.91", "start_time_ms": 1780790400000, "upper_boundary": "1845.09"}, {"description": "Bull leg, bars 37-50: higher closes from bar 37's 1597.72 low to bar 50's 1944.39 high, including a large bull bar at 49 (open 1775.60, close 1889.93) and a 1804.49-1828.20 high zone at bars 40-41. This leg lifts price out of the 1512.91-1845.09 base.", "end_time_ms": 1784073599999, "kind": "swing", "lower_boundary": "1597.72", "start_time_ms": 1782950400000, "upper_boundary": "1944.39"}, {"description": "Large trading range, bars 51-84: 34 bars rotating between 1803.74 (bar 52 low) and 1974.46 (bar 62 high), with 1954-1959 highs at bars 57 and 61; bars 74-84 compress into a tight ~1868-1919 zone on small bodies before the breakout.", "end_time_ms": 1787097599999, "kind": "range", "lower_boundary": "1803.74", "start_time_ms": 1784073600000, "upper_boundary": "1974.46"}, {"description": "Bull spike, bars 85-87: bar 85 breaks the 34-bar range with a 388-point bar (open 1916.51, high 2293.80, close 2252.16), and bars 86-87 continue to 2771, an ~850-point advance in three bars.", "end_time_ms": 1787356799999, "kind": "breakout", "lower_boundary": "1905.63", "start_time_ms": 1787097600000, "upper_boundary": "2771"}, {"description": "Bull-flag range, bars 88-107: 20 overlapping bars between 2357.18 (bar 99 low) and 2557.46 (bar 93 high), all holding far above the bar-85 breakout low; bar 112 later dips back to 2358.62 inside this general zone.", "end_time_ms": 1788998399999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1787356800000, "upper_boundary": "2557.46"}, {"description": "Second bull breakout, bars 108-119: bar 108 (open 2437) closes 2514.72 at high 2680, a five-bar pullback reaches 2358.62 (bar 112), then bars 115-118 run to a new window high 2850 (bar 118, close 2775.61) before bar 119 stalls with a 2776.18 high.", "end_time_ms": 1790035199999, "kind": "breakout", "lower_boundary": "2358.62", "start_time_ms": 1789084800000, "upper_boundary": "2850"}], "symbol": "ETH-USDT", "timeframe": "D1", "transition_conditions": ["Bull continuation: a daily close above 2850 (bar 118 high) with the close in the upper half of the bar and no close below 2716.01 (bar 119 low) keeps the breakout-spike read and extends the higher-high sequence.", "Shift to range: several consecutive closes back inside 2357.18-2557.46 (the bar 88-107 band) without a new high would make the post-bar-85 structure a trading range and move phase toward 'range'.", "Trend-doubt: a close below 2436.87 (bar 115 low) or 2435.72 (bar 108 low) would break the higher low that the latest leg tested and push primary_regime toward transition-unclear.", "Larger reversal evidence: a close below 2358.62 (bar 112 low) followed by a lower swing high would break the last higher low of the bull sequence and make a retracement toward 2111 (bar 86 low) the dominant structural read.", "Acceleration or exhaustion: another bull bar with a range above 250 closing at a new high confirms the spike phase, while a bear reversal bar closing below 2716.01 after a new high would raise the mtr-like top alternative to the current read."], "window_bars": 120}, "freshness": "current"}, "H4": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1790121599999, "directional_pressure": "bull", "evidence_against": ["Roughly 100 of the 120 bars are overlapping two-sided trade between 2358.62 and 2700.00; only the final ~12-26 bars are directional, so the bull-trend label rests on a short segment of the window.", "The breakout bar itself left a large upper tail (high 2850.00 vs close 2723.15) and the last seven bars could not exceed 2804.59, with highs stepping down - consistent with a stall/final-flag shape rather than fresh trend strength.", "Same-window precedent: the 1789128000000 spike to 2680.00 with a big upper tail failed outright and was followed by a multi-bar decline to 2358.62, showing a spiky high here has not always been accepted.", "No second clear bull spike has followed the breakout; the last seven bars have small bodies and heavy overlap, so continuation is unproven and a failed-breakout reversal remains possible."], "evidence_for": ["Decisive break of a well-tested 2700.00 boundary (highs at 1789804800000 and 1789948800000) by a wide-range bull bar (2658.81 -> 2723.15, high 2850.00).", "Follow-through after the breakout: closes 2754.31, 2760.51, 2775.61 are the highest of the window, and no close has returned below 2700.00, so the broken boundary has held as support so far.", "Higher swing lows in the final third (2358.62 -> 2568.16 -> 2716.01) and a window high (2850.00) above every earlier high (2537.57, 2680.00, 2700.00) show a rising sequence, not a lower-high structure.", "The close at 2752.43 sits above the 2700.00 breakout point and in the upper half of the last seven-bar range, so the latest bars have not given back the breakout."], "missing_information": [], "observations": ["Window opens 2391.94 and closes 2752.43; window high 2850.00 and window low 2358.62.", "Most of the window (1788393600000-1789948800000, ~100 bars) is overlapping two-sided trade between 2358.62 and 2700.00: deep pullbacks to 2411.04 (1789041600000) and 2358.62 (1789488000000), repeated tests of 2520-2609, small bodies and long tails throughout.", "Resistance at 2700.00 was tested twice (highs at 1789804800000 and 1789948800000) before the breakout; the earlier spike high at 2680.00 (1789128000000) failed.", "Breakout bar 1789977600000 opened 2658.81, reached 2850.00 and closed 2723.15 (large bull body with a ~127-point upper tail).", "Follow-through closes after the breakout: 2754.31, 2760.51, 2775.61 - the highest closes in the window; no close since the breakout has printed below 2700.00 (lowest close 2724.95 at 1790049600000).", "Last seven bars are a tight overlapping range between 2716.01 (low 1790049600000) and 2776.18 (high 1790035200000); highs step down 2804.59 -> 2776.18 -> 2767.30 while lows hold 2722.62-2737.75, and the final bar closes 2752.43 mid-to-upper inside that range.", "Rising swing lows in the final third: 2358.62 (1789488000000) -> 2568.16 (1789891200000) -> 2716.01 (1790049600000); the 2850.00 high exceeds all earlier window highs (2537.57 at 1788508800000, 2680.00 at 1789128000000, 2700.00 twice)."], "phase": "range", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Broad two-sided trading range covering most of the window: repeated failure near 2520-2609 and support from 2358.62-2411.04, with heavy bar overlap and deep pullbacks; the 2700.00 highs mark the range's upper extreme before the breakout.", "end_time_ms": 1789948800000, "kind": "range", "lower_boundary": "2358.62", "start_time_ms": 1788537600000, "upper_boundary": "2700.00"}, {"description": "Bull breakout above the 2700.00 double top: bar 1789977600000 opened 2658.81, reached 2850.00 and closed 2723.15; the next three bars closed 2754.31, 2760.51 and 2775.61 and price has not closed back below 2700.00 since, which is acceptance above the broken boundary so far.", "end_time_ms": 1790020800000, "kind": "breakout", "lower_boundary": "2700.00", "start_time_ms": 1789977600000, "upper_boundary": "2850.00"}, {"description": "Tight consolidation / bull-flag area after the breakout: seven small overlapping bars between 2716.01 and 2776.18 with slightly declining highs (2804.59 high at 1790020800000, then 2776.18, then 2767.30) and flat lows; two-sided trade rather than a fresh directional push.", "end_time_ms": 1790107200000, "kind": "two-sided", "lower_boundary": "2716.01", "start_time_ms": 1790035200000, "upper_boundary": "2776.18"}, {"description": "Earlier buy-climax-style spike bar: 1789128000000 opened 2457.12, spiked to 2680.00 and closed 2555.52 (~125 points of upper tail); it was not accepted and the market drifted down about 320 points to 2358.62 over the following bars.", "end_time_ms": 1789128000000, "kind": "climax", "lower_boundary": null, "start_time_ms": 1789128000000, "upper_boundary": "2680.00"}, {"description": "Rising swing-low sequence in the final third of the window: 2358.62 (1789488000000) -> 2568.16 (1789891200000) -> 2716.01 (1790049600000), each low well above the prior one.", "end_time_ms": 1790049600000, "kind": "swing", "lower_boundary": "2358.62", "start_time_ms": 1789488000000, "upper_boundary": null}], "symbol": "ETH-USDT", "timeframe": "H4", "transition_conditions": ["Bull continuation: a close above 2804.59, or a strong bull bar closing above the 2776.18 range high with immediate follow-through, would confirm acceptance of the breakout and shift the read from a pause toward a resumed channel/spike.", "Bear transition: consecutive closes below 2716.01, and especially a close back below 2700.00, would mark a failed breakout; a lower high below 2850.00 followed by a lower low would build an mtr-like reversal structure.", "Sideways persistence: continued overlapping bars between 2716.01 and 2776.18 with no boundary break keeps the market in a bull flag / tight range and keeps Always-In relevance low-to-medium.", "Regime shift: a sustained return into the 2358.62-2700.00 area and acceptance there would move primary_regime back toward trading-range."], "window_bars": 120}, "freshness": "stale"}}, "raw": {"H1": [{"close": "2480.3", "close_time_ms": 1789707599999, "high": "2480.35", "low": "2469.24", "ope